    // certificate, never be merged into an astral character and displayed.
    let content = bmp_units(&[0xD83D, 0xDE00]);
    let subject = name(&[rdn(&[atv_bmp(CN, &content)])]);
    let issuer = simple_cn_name("Test CA");
