    for bad in [
        vec![0x00],
        vec![0x00, 0x61],
        vec![0x00, 0x00, 0x61],
        [&legal[..], &[0x00]].concat(),
        [&legal[..], &[0x00, 0x00]].concat(),
        [&legal[..], &[0x00, 0x00, 0x00]].concat(),
